            modelBuilder.Entity("PortalItlock.Web.Models.TilbudForside", b =>
                {
                    b.Property<int>("Id")
                        .ValueGeneratedOnAdd()
                        .HasColumnType("INTEGER");

                    b.Property<string>("Innhold")
